//
// npm run dev:load [file]: replaces the LOCAL emulator data with a saved copy (default .emulator/live-copy.json, written by npm run dev:pull)
// and gives everyone in it a local account to sign in as: the copied Auth accounts with their own uid, or, when the copy has none, one per
// email address found in the data.
//
// The data it replaces is first saved to .emulator/backup-before-load-<time>.json (a file this same command loads again: npm run dev:load --
// <that file>); --no-backup skips that. Only one load/seed runs at a time.
import fs from "node:fs";
import path from "node:path";
import { ROOT, DATA_DIR, PENDING_COPY, HOSTING_URL, requireEmulators, replaceLocalData, decoderFor, validateDocs, validatePeople, parseArgs } from "./emulator.mjs";

const { flags, positional } = parseArgs(process.argv.slice(2), ["--no-backup"], 1);
const file = path.resolve(positional[0] || path.join(DATA_DIR, "live-copy.json"));
if (!fs.existsSync(file)) {
  console.error(`No saved copy at ${path.relative(ROOT, file)}. Make one with: npm run dev:pull`);
  process.exit(1);
}
let copy;
try {
  copy = JSON.parse(fs.readFileSync(file, "utf8"));
} catch (err) {
  console.error(`${path.relative(ROOT, file)} is not a saved copy (${err.message}). Nothing was changed; make a new one with: npm run dev:pull`);
  process.exit(1);
}
if (!copy || !Array.isArray(copy.docs) || copy.docs.some((d) => !d || typeof d.path !== "string" || !d.path || !d.data || typeof d.data !== "object")) {
  console.error(`${path.relative(ROOT, file)} does not look like a saved copy (it needs a docs list of { path, data }). Nothing was changed; make a new one with: npm run dev:pull`);
  process.exit(1);
}

function emailsIn(docs) {
  const found = new Set();
  const EMAIL = /^[^\s@/]+@[^\s@/]+\.[a-z]{2,}$/i;
  const visit = (v) => {
    if (typeof v === "string") { if (EMAIL.test(v)) found.add(v.toLowerCase()); }
    else if (Array.isArray(v)) v.forEach(visit);
    else if (v && typeof v === "object") { Object.keys(v).forEach(visit); Object.values(v).forEach(visit); }
  };
  for (const d of docs) { d.path.split("/").forEach(visit); visit(d.data); }
  return [...found].sort();
}

// Everything is read, decoded and checked BEFORE the emulators are wiped: a damaged copy must not leave the local data empty.
const refuse = (what, err) => {
  console.error(`${what} (${err.message}). Nothing was changed; make a new one with: npm run dev:pull`);
  process.exit(1);
};
let docs;
try {
  const decodeData = decoderFor(copy.version);
  docs = copy.docs.map(({ path: p, data }) => ({ path: p, data: decodeData(data) }));
} catch (err) {
  refuse("The saved copy cannot be decoded", err);
}
let people, warnings;
try {
  validateDocs(docs);
  // A copy of production data: an account the emulator cannot take is left out with a warning, it does not make the whole copy unloadable.
  ({ people, warnings } = validatePeople(copy.accounts || emailsIn(copy.docs).map((email) => ({ email })), { live: true }));
} catch (err) {
  refuse("The saved copy is not usable", err);
}
for (const w of warnings) console.warn(`Warning, ${w}`);

await requireEmulators();
await replaceLocalData("load", { docs, people, source: file, backup: !flags.has("--no-backup") });
fs.rmSync(PENDING_COPY, { force: true }); // loaded: the next start keeps whatever is in the emulators

console.log(`Loaded ${copy.docs.length} documents from ${copy.project}, copied ${copy.pulledAt}. ${people.length} accounts to sign in as${copy.accounts ? "" : " (made from the email addresses in the data)"}.${HOSTING_URL ? ` Open ${HOSTING_URL}` : ""}`);
process.exit(0);
